<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<style>
    body {
        font-family: "Times New Roman", Times, Georgia, serif;
        font-size: 11.5px;
        line-height: 1.18;
        color: #111;
        background-color: #f7f6f0;
        margin: 0;
        padding: 20px;
        display: flex;
        justify-content: center;
    }

    .gazette-page {
        width: 900px;
        background-color: #fffdfa;
        padding: 15px 20px;
        box-shadow: 0 0 10px rgba(0,0,0,0.15);
        border: 1px solid #d3cfc5;
    }

    /* Cabeçalho */
    .header {
        text-align: center;
        position: relative;
        padding-bottom: 5px;
        border-bottom: 2px solid #000;
        margin-bottom: 2px;
    }

    .header-sub-border {
        border-bottom: 1px solid #000;
        padding-bottom: 3px;
        margin-bottom: 8px;
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
    }

    .header-left {
        font-size: 15px;
        font-weight: bold;
        letter-spacing: 1px;
    }

    .header-title {
        font-size: 19px;
        font-weight: bold;
        letter-spacing: 2px;
        text-transform: uppercase;
        margin: 0;
    }

    .header-right {
        font-size: 13px;
        font-weight: bold;
    }

    /* Colunas */
    .columns-container {
        display: grid;
        grid-template-columns: 1fr 1fr 1.08fr;
        column-gap: 12px;
    }

    .column {
        text-align: justify;
        text-justify: inter-word;
        border-right: 1px solid #111;
        padding-right: 12px;
    }

    .column:last-child {
        border-right: none;
        padding-right: 0;
    }

    /* Tipografia e Títulos de Seção */
    .section-title {
        text-align: center;
        font-size: 10px;
        font-weight: bold;
        letter-spacing: 0.5px;
        text-transform: uppercase;
        margin: 7px 0 3px 0;
    }

    .main-section-title {
        text-align: center;
        font-size: 12.5px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        margin: 2px 0;
    }

    .main-section-subtitle {
        text-align: center;
        font-size: 11px;
        font-weight: bold;
        text-transform: uppercase;
        letter-spacing: 0.5px;
        margin: 0 0 6px 0;
    }

    p {
        margin: 0 0 5px 0;
        text-indent: 10px;
    }

    p.no-indent {
        text-indent: 0;
    }

    .em-dash {
        margin-right: 2px;
    }

    /* Tabela do Balancete */
    .balancete-box {
        margin-top: 8px;
        font-size: 10px;
        line-height: 1.15;
    }

    .balancete-header {
        font-weight: bold;
        text-align: center;
        text-transform: uppercase;
        font-size: 10px;
        margin-bottom: 6px;
    }

    .balance-line {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        margin-bottom: 1px;
    }

    .balance-label {
        flex: 1;
        white-space: nowrap;
        overflow: hidden;
        position: relative;
    }

    .balance-label::after {
        content: " ...................................................................................";
        position: absolute;
        padding-left: 2px;
        color: #333;
    }

    .balance-label-clean {
        flex: 1;
    }

    .balance-val {
        text-align: right;
        white-space: nowrap;
        padding-left: 4px;
        font-variant-numeric: tabular-nums;
    }

    .subtotal-val {
        border-top: 1px solid #111;
        border-bottom: 1px solid #111;
        margin-left: 8px;
    }

    .total-val {
        border-top: 1px solid #111;
        border-bottom: 3px double #111;
        font-weight: bold;
    }

    .indent-1 {
        padding-left: 8px;
    }

    .bold-title {
        font-weight: bold;
        text-transform: uppercase;
        margin-top: 4px;
        display: block;
    }
</style>
</head>
