                    <span class="balance-val">527:535$310</span>
                </div>
                <div class="balance-line indent-1">
                    <span class="balance-label">Em caixa</span>
                    <span class="balance-val">2.194:945$039</span>
                    <span class="balance-val subtotal-val">2.722:480$349</span>
                </div>
                <div class="balance-line">
                    <span class="balance-label">Entradas até hoje</span>
                    <span class="balance-val subtotal-val">373:285$691</span>
                </div>
